import{_ as a,o as r,c as s,ai as e}from"./chunks/framework.Ba-VnP44.js";const b=JSON.parse('{"title":"副业方向选择与设计","description":"","frontmatter":{},"headers":[],"relativePath":"ai/business/side-business-design.md","filePath":"ai/business/side-business-design.md"}'),i={name:"ai/business/side-business-design.md"};function n(d,t,l,o,h,g){return r(),s("div",null,[...t[0]||(t[0]=[e('<h1 id="副业方向选择与设计" tabindex="-1">副业方向选择与设计 <a class="header-anchor" href="#副业方向选择与设计" aria-label="Permalink to “副业方向选择与设计”">​</a></h1><h2 id="背景" tabindex="-1">背景 <a class="header-anchor" href="#背景" aria-label="Permalink to “背景”">​</a></h2><p>方向筛完（挖掘需求 + 机会打分），落到执行层面还有一个更朴素的问题：<strong>你打算用哪种姿势赚钱？</strong> 同样是「会写代码 + 会用 AI」，走定制开发、技术顾问、录课、还是做内容，四条路的现金流曲线、时间结构、和主业的冲突程度完全不同。选错路径的代价不是赚得少，而是做了半年发现这条路和你的生活结构根本不兼容——比如需要随时在线接单的人，配不了「上班不敢开手机」的工作。</p><p>这篇不谈哪个方向「最赚钱」（公开场景下没人能诚实回答这个问题），只做结构对比：四条路径各自的运作方式、时间成本、冲突点，以及怎么选第一路径、怎么组合。</p><h2 id="拆解" tabindex="-1">拆解 <a class="header-anchor" href="#拆解" aria-label="Permalink to “拆解”">​</a></h2><h3 id="_1-四条路径对比" tabindex="-1">1. 四条路径对比 <a class="header-anchor" href="#_1-四条路径对比" aria-label="Permalink to “1. 四条路径对比”">​</a></h3><table tabindex="0"><thead><tr><th>路径</th><th>卖什么</th><th>现金流特征</th><th>启动难度</th><th>与主业冲突度</th></tr></thead><tbody><tr><td>定制开发</td><td>你的工时 + 交付物</td><td>快，单结；但一单一停</td><td>低（有单即启动）</td><td><strong>高</strong>，工期撞加班就崩</td></tr><tr><td>技术顾问</td><td>判断与经验（按时间/按项目）</td><td>中速，客单较高</td><td>中，需要信任背书</td><td>中，可谈节奏</td></tr><tr><td>课程/教程</td><td>沉淀好的知识产品</td><td>慢，先投入后长尾</td><td>高，制作周期长</td><td>低，可碎片打磨</td></tr><tr><td>内容（公众号/视频）</td><td>注意力与信任</td><td>最慢，先积累后变现</td><td>低（发布容易）</td><td>低-中，需持续更新</td></tr></tbody></table><p>逐条说透各自的真相：</p><p><strong>定制开发</strong>：离钱最近的一条路。你在职期间接外包、接朋友介绍的活，一单几千到几万，现金流立刻可见。但它的本质是<strong>用业余时间打第二份工</strong>——没有复利，停下归零，且交付压力会直接吃掉学习和休息时间。适合作为启动期的现金来源，不宜当终局。</p><p><strong>技术顾问</strong>：定制开发的升级形态，卖的是判断而非工时。典型形态：帮小团队做架构评审、给传统企业做数字化方案、做 AI 落地咨询。客单更高、耗时更少，但<strong>要求你有可展示的资历和敢开口的自信</strong>。10 年经验是这个方向的本钱，多数人缺的不是能力是第一个客户。</p><p><strong>课程/教程</strong>：边际成本最低的一条。录一次卖多次，睡后收入是真的。但制作周期长（认真做一门课通常要两三个月业余时间），且市场早已从「有课就行」卷到「有流量才有课」。务实做法不是一上来做大课，而是<strong>从 90 分钟的付费小课、一份付费文档开始试水</strong>。</p><p><strong>内容</strong>：启动成本最低、变现最慢的一条，前面案例拆解已详述。它的独立价值在于：<strong>无论最终卖什么，内容都是获客与信任的放大器</strong>，四条路径几乎都能叠加它。</p><h3 id="_2-时间成本-先算清你的真实预算" tabindex="-1">2. 时间成本：先算清你的真实预算 <a class="header-anchor" href="#_2-时间成本-先算清你的真实预算" aria-label="Permalink to “2. 时间成本：先算清你的真实预算”">​</a></h3><p>副业设计的第一步不是选方向，是<strong>盘点时间</strong>。诚实的算法：</p><ul><li>工作日：扣除通勤、加班、家庭责任后，真正可支配的多数人只有 1-1.5 小时；</li><li>周末：按 8-10 小时估，但每月至少有一半周末会被生活事务吃掉；</li><li>结论：<strong>多数在职者的可持续预算是每周 10 小时左右</strong>，且要留出不为副业的时间缓冲。</li></ul><p>用这个预算反推路径：每周 10 小时做不了需要随时响应的定制开发（会违约），做得了固定时段的内容更新和顾问的预约制沟通。把「我有大把时间」当前提是副业计划失败的头号原因。</p><h3 id="_3-与主业的冲突管理" tabindex="-1">3. 与主业的冲突管理 <a class="header-anchor" href="#_3-与主业的冲突管理" aria-label="Permalink to “3. 与主业的冲突管理”">​</a></h3><p>三类冲突要分别设防：</p><p><strong>精力冲突</strong>：最隐蔽也最致命。副业排满每个晚上 → 三个月后慢性疲劳 → 主业出错 → 得不偿失。规则：每周固定上限（如 10 小时），超了就砍需求，不砍睡眠。</p><p><strong>时间冲突</strong>：项目 deadline 撞上副业交付期。规则：副业承诺永远留 50% buffer；接单合同写清交付窗口；主业忙季主动降级副业节奏（内容改周更、顾问暂停新单）。</p><p><strong>合规与利益冲突</strong>（这条不能含糊）：</p><ul><li>查清劳动合同里的兼职、竞业、知识产权条款——<strong>在职期间的代码类副业，权属风险是真实存在的</strong>；</li><li>不接与主业存在竞争或利益输送嫌疑的单子；</li><li>不动用主业的内部资源、客户、数据做副业；</li><li>收入达到一定规模，主动了解个税申报义务（详见「变现路径与定价」）。</li></ul><p>冲突管理的总原则：<strong>副业永远是主业的下游</strong>。这不是保守，是数学——你的医保、公积金和主要现金流都在主业里，副业在验证成功前不值得你拿主业去赌。</p><h3 id="_4-怎么选-第一路径与组合拳" tabindex="-1">4. 怎么选：第一路径与组合拳 <a class="header-anchor" href="#_4-怎么选-第一路径与组合拳" aria-label="Permalink to “4. 怎么选：第一路径与组合拳”">​</a></h3><ul><li>现金紧张、想尽快见到回头钱 → <strong>定制开发</strong>起步，用单子逼自己完成「对外交付」第一次；</li><li>有资历、有表达欲 → <strong>顾问</strong>起步，从给熟人公司一次付费分享开始；</li><li>有沉淀、表达成体系 → <strong>小课/付费文档</strong>试水；</li><li>什么都不确定 → <strong>内容</strong>起步，反正成本最低，还能顺带验证另外三条路的方向。</li></ul><p>多数人的最优解其实是组合：<strong>前期定制开发供血 + 内容积累信任，中期把重复交付沉淀成课程或产品，长期靠顾问与产品</strong>。路径不是三选一的单选题，而是一条随时间迁移的流水线。</p><h2 id="关键要点" tabindex="-1">关键要点 <a class="header-anchor" href="#关键要点" aria-label="Permalink to “关键要点”">​</a></h2><ul><li>四条路径的本质差别：定制卖工时（快但无复利）、顾问卖判断（看资历）、课程卖沉淀（慢启动快长尾）、内容卖信任（最慢但可叠加）；</li><li>先盘点真实时间预算（多数人每周约 10 小时），再让路径适配预算，而不是反过来；</li><li>冲突三设防：精力设上限、时间留 buffer、合规查合同——副业永远是主业的下游；</li><li>第一条路径按现状选：缺钱做开发、有资历做顾问、有沉淀做课、不确定就先做内容；</li><li>路径是会迁移的流水线：开发供血 → 内容蓄水 → 沉淀成产品 → 顾问收尾。</li></ul><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to “小结”">​</a></h2><p>副业设计没有标准答案，但有标准的思考顺序：算清时间 → 排掉合规雷 → 选与生活结构兼容的第一路径 → 允许自己随阶段迁移。10 年工程经验在这四条路里都是本钱，真正的约束从来不是能力，而是每周那 10 个小时和你愿意承受的方差。选一条跑得动的，比选一条想象中赚得大的，重要得多。</p>',30)])])}const c=a(i,[["render",n]]);export{b as __pageData,c as default};
